var dummyHash = auth.HashPassword(auth.NewOpaqueToken())

// authenticate returns the user whose email and password match.
// Unknown emails still pay for one hash, so both failures take as long.
func (h *AuthHandler) authenticate(r *http.Request, c credentials) (postgres.User, error) {
	u, err := h.Users.ByEmail(r.Context(), strings.TrimSpace(c.Email))
	if errors.Is(err, domain.ErrNotFound) || (err == nil && u.PasswordHash == nil) {
		auth.VerifyPassword(dummyHash, c.Password)
		return u, unauthorized("Email or password is incorrect.")
	}
	if err != nil {
		return u, err
	}
	ok, err := auth.VerifyPassword(*u.PasswordHash, c.Password)
	if err != nil || !ok {
		return u, unauthorized("Email or password is incorrect.")
	}
	if auth.NeedsRehash(*u.PasswordHash) {
		err = h.Users.UpdatePasswordHash(r.Context(), u.ID, auth.HashPassword(c.Password))
	}
	return u, err
}

func (h *AuthHandler) startSession(w http.ResponseWriter, r *http.Request, userID int64) error {
	if old, err := r.Cookie(sessionCookie); err == nil {
		if err := h.Sessions.Delete(r.Context(), auth.HashToken(old.Value)); err != nil {
			return err
		}
	}
	token := auth.NewOpaqueToken()
	if err := h.Sessions.Create(r.Context(), auth.HashToken(token), userID, sessionLifetime); err != nil {
		return err
	}
	http.SetCookie(w, &http.Cookie{
		Name:     sessionCookie,
		Value:    token,
		Path:     "/",
		MaxAge:   int(sessionLifetime.Seconds()),
		Secure:   true,
		HttpOnly: true,
		SameSite: http.SameSiteLaxMode,
	})
	return nil
}

func (h *AuthHandler) logOut(w http.ResponseWriter, r *http.Request) error {
	if c, err := r.Cookie(sessionCookie); err == nil {
		if err := h.Sessions.Delete(r.Context(), auth.HashToken(c.Value)); err != nil {
			return err
		}
	}
	http.SetCookie(w, &http.Cookie{Name: sessionCookie, Value: "", Path: "/", MaxAge: -1,
		Secure: true, HttpOnly: true, SameSite: http.SameSiteLaxMode})
	w.WriteHeader(http.StatusNoContent)
	return nil
}

