type AccessClaims struct {
	Role       string `json:"role"`
	BuildingID *int64 `json:"building_id"`
	Scope      string `json:"scope"`
	jwt.RegisteredClaims
}

type AccessTokens struct{ key []byte }

func NewAccessTokens(key []byte) *AccessTokens { return &AccessTokens{key: key} }

func (t *AccessTokens) Issue(userID int64, role string, buildingID *int64, scopes []string) (string, error) {
	now := time.Now()
	claims := AccessClaims{
		Role:       role,
		BuildingID: buildingID,
		Scope:      strings.Join(scopes, " "),
		RegisteredClaims: jwt.RegisteredClaims{
			Subject:   strconv.FormatInt(userID, 10),
			Issuer:    Issuer,
			Audience:  jwt.ClaimStrings{Audience},
			IssuedAt:  jwt.NewNumericDate(now),
			ExpiresAt: jwt.NewNumericDate(now.Add(AccessTokenLifetime)),
			ID:        rand.Text(),
		},
	}
	return jwt.NewWithClaims(jwt.SigningMethodHS256, claims).SignedString(t.key)
}

func (t *AccessTokens) Verify(token string) (*AccessClaims, error) {
	claims := &AccessClaims{}
	_, err := jwt.ParseWithClaims(token, claims,
		func(*jwt.Token) (any, error) { return t.key, nil },
		jwt.WithValidMethods([]string{"HS256"}),
		jwt.WithIssuer(Issuer),
		jwt.WithAudience(Audience),
		jwt.WithExpirationRequired(),
		jwt.WithIssuedAt(),
	)
	if err != nil {
		return nil, err
	}
	return claims, nil
}
